void ProviderAgent::cancel()
{
    if (m_transport)
        m_transport->cancel();
    ++m_http_generation;
    {
        std::lock_guard<std::mutex> lock(m_mutex);
        m_http_events.clear();
    }
    m_events.clear();
    m_sse_buffer.clear();
    m_queued_calls.clear();
    m_busy = false;
    m_waiting_for_tool = false;
    m_terminal_seen = true;
}

