}
.turn-activity-action.edit { color: var(--text-primary); }
.turn-activity-action.state-failed { color: var(--status-danger); }
.turn-activity-action-text {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

